// Writes the party sounds in assets/sounds into frontend/utils/partySoundData.ts as base64, so the
// plugin carries them inside its bundle. Run it after changing a sound: node tools/embed-sounds.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const sounds = { popper: 'assets/sounds/popper.mp3', horn: 'assets/sounds/horn.mp3' };
const lines = [
	'// Generated by tools/embed-sounds.mjs from assets/sounds. Edit those files, not this one.',
	'// See assets/sounds/CREDITS.md for where the sounds come from.',
	'',
];
for (const [name, file] of Object.entries(sounds)) {
	const data = readFileSync(file).toString('base64');
	lines.push(`export const ${name}Mp3 = 'data:audio/mpeg;base64,${data}';`);
}
writeFileSync('frontend/utils/partySoundData.ts', lines.join('\n') + '\n');
console.log('Wrote frontend/utils/partySoundData.ts');
